const {fitDataAsync, OPTIMIZERS} = DataScience;
const {vec} = NMath;
const {vertices} = await IO.loadMesh("/assets/bunny.obj");
if (vertices.length === 0) throw new Error("The bunny mesh contains no vertices");

// Center, scale, and orient the bunny as in the flow-matching demo.
const points = vertices.map(vertex => vec(...vertex));
const mean = points.reduce((sum, point) => sum.add(point), vec.zero(3)).scale(1 / points.length);
const centered = points.map(point => point.sub(mean));
const scale = Math.max(...centered.flatMap(point => point.components.map(Math.abs)));
if (!Number.isFinite(scale) || scale === 0) throw new Error("The bunny mesh has invalid coordinates");
const targets = centered.map(point => {
    const [x, y, z] = point.scale(1 / scale).components;
    return vec(z, x, y);
});
const model = HKmeans.new(targets, {rho: 0.1, kmeansIter: 2}).fit();
const neighbors = 4;
const smoothing = 16;
const smoothUnion = (a, b) => HKmeans.CombinationFn.SMOOTH_UNION(a, b, smoothing);
const udf = point => model.udf(point, neighbors, smoothUnion);

const padding = 0.1;
const min = [0, 1, 2].map(axis => Math.min(...targets.map(point => point.components[axis])) - padding);
const max = [0, 1, 2].map(axis => Math.max(...targets.map(point => point.components[axis])) + padding);
const randomPoint = () => vec(...min.map((value, axis) => value + Math.random() * (max[axis] - value)));

// Central differences approximate the UDF gradient away from its non-differentiable points.
const h = 0.001;
const gradient = point => {
    const offsets = [vec(h, 0, 0), vec(0, h, 0), vec(0, 0, h)];
    return vec(...offsets.map(offset => (udf(point.add(offset)) - udf(point.sub(offset))) / (2 * h)));
};
const samples = Array.from({length: 10000}, () => {
    const point = randomPoint();
    return {point, gradient: gradient(point)};
});

// The network learns the gradient; its negative is used as the flow velocity.
const field = NeuralNet.builder()
    .input(3)
    .layer(24)
    .layer(24)
    .layer(3, NeuralNet.ACTIVATIONS.linear)
    .build();
const initial = Array.from({length: 800}, randomPoint);
const plot = IO.plotPointCloud(targets, {aspect: "equal", radius: 0.008, color: [0.4, 0.4, 0.4]});
const moving = plot.add(initial, {radius: 0.012, color: [1, 0, 0]});
const arrows = plot.addLines([], {color: [0.35, 0.65, 1], radius: 0.003});
plot.add([min, max], {color: [0, 0, 0]});
const steps = 100;
let time = 0;
let noiseLevel = 0.1;
let trajectory;

// Show a sparse grid of capped negative-gradient arrows.
const fieldLines = () => {
    const lines = [];
    for (let i = 0; i <= 4; i++) {
        for (let j = 0; j <= 4; j++) {
            for (let k = 0; k <= 4; k++) {
                const start = vec(min[0] + i * (max[0] - min[0]) / 4, min[1] + j * (max[1] - min[1]) / 4, min[2] + k * (max[2] - min[2]) / 4);
                const velocity = vec(...field.eval(start)).scale(-1);
                const length = velocity.length();
                if (length < 1e-8) continue;
                const delta = velocity.scale(Math.min(0.1, 0.2 / length));
                const end = start.add(delta);
                const [dx, dy, dz] = delta.components;
                const perpendicular = Math.abs(dx) + Math.abs(dy) > 1e-8
                    ? vec(-dy, dx, 0) : vec(0, -dz, dy);
                const side = perpendicular.scale(0.15 * delta.length() / perpendicular.length());
                const head = delta.scale(0.3);
                lines.push([start, end], [end, end.sub(head).add(side)], [end, end.sub(head).sub(side)]);
            }
        }
    }
    return lines;
};
const showTime = t => {
    if (!trajectory) return;
    time = t;
    moving.update(trajectory[Math.round(t * steps)], {color: [1 - t, t, 0]});
    plot.render();
};
const ui = IO.UI(
    {type: "canvas", value: () => plot},
    {type: "slider", value: () => ({
        title: "t:", min: 0, max: 1, step: 1 / steps, value: 0,
        onChange: showTime,
    })},
    {type: "slider", value: () => ({
        title: "Noise:", min: 0, max: 0.2, step: 0.01, value: noiseLevel,
        onChange: value => { noiseLevel = value; generateTrajectory(); showTime(time); },
    })},
);

const {theta} = await fitDataAsync(
    samples.map(sample => sample.point),
    samples.map(sample => sample.gradient),
    field.model,
    {
        epochs: 5000,
        batch: 32,
        optimizer: OPTIMIZERS.ADAMW({learningRate: 0.005}),
        continuationEvery: 250,
        continuationFn: ({epoch, loss}) => console.log(`Epoch ${epoch + 1}, loss ${loss.toFixed(4)}`),
    },
);
field.setWeights(theta);

// Precompute trajectories so the sliders can move both forwards and backwards.
const generateTrajectory = () => {
    trajectory = [initial];
    for (let step = 0; step < steps; step++) {
        trajectory.push(trajectory[step].map(point => {
            const velocity = vec(...field.eval(point)).scale(-1);
            const noise = vec.fromArray(NMath.mat.random(1, point.dim, {distribution: "gaussian"}).data);
            const noiseScale = noiseLevel * (1 - step / (steps - 1)) / Math.sqrt(steps);
            return point.add(velocity.scale(1 / steps)).add(noise.scale(noiseScale));
        }));
    }
};
generateTrajectory();
arrows.update(fieldLines());
showTime(0);
ui;
